-- Materi BKV-12 (Blok 12 Sistem Kardiovaskuler): 20 bahasan PDF dalam 4 kelompok.
-- Dibuat oleh prisma/bkv12-materi.py; berkas PDF & gambar halaman sudah ada di storage server.
-- Aman dijalankan pada database kosong (semua INSERT bergantung pada Blok BKV-12 yang ada).

-- Topik lama yang masih terbit (contoh 'Bab 1') disembunyikan, riwayatnya tetap.
UPDATE Topic SET published = false WHERE categoryId = (SELECT id FROM Category WHERE code = 'BKV-12') AND published = true AND id NOT LIKE 'dea-bkv12-%';
-- Deskripsi kelas bawaan menyebut kuis per Bab; diganti hanya bila belum diubah admin.
UPDATE Category SET description = 'Blok 12 tahap akademik (preklinik). 20 bahasan fisiologi kardiovaskular dalam 4 bagian, dari struktur dan listrik jantung hingga korelasi penyakit. Bagian 1 (bahasan 1–5) gratis untuk akun terdaftar.' WHERE code = 'BKV-12' AND description LIKE 'Blok 12 tahap akademik (preklinik). Materi dibagi per Bab%';

INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bkv12-group-1', id, 'Struktur dan Aktivitas Listrik Jantung', 'Bahasan 1–5. Gratis untuk semua akun terdaftar.', 1, true FROM Category WHERE code = 'BKV-12';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bkv12-group-2', id, 'Mekanika Jantung dan Dasar Aliran Darah', 'Bahasan 6–10. Tersedia untuk pemilik paket Blok Kardiovaskuler atau Basic Medical Science.', 2, true FROM Category WHERE code = 'BKV-12';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bkv12-group-3', id, 'Pembuluh Darah dan Regulasi Sirkulasi', 'Bahasan 11–15. Tersedia untuk pemilik paket Blok Kardiovaskuler atau Basic Medical Science.', 3, true FROM Category WHERE code = 'BKV-12';
INSERT OR IGNORE INTO Topic (id, categoryId, title, description, "order", published) SELECT 'dea-bkv12-group-4', id, 'Korelasi Penyakit dan Penerapan Dasar', 'Bahasan 16–20. Tersedia untuk pemilik paket Blok Kardiovaskuler atau Basic Medical Science.', 4, true FROM Category WHERE code = 'BKV-12';

